slawsSetup();
function dailyEligible(p){let r=p.role||{};return p.upcoming.week===slawsActiveWeek&&p.availability?.status==="available"&&(r.likely_starter===true||Number.isFinite(r.expected_snap_pct)&&r.expected_snap_pct>=.55)}
function dailyLine(p,m,risk=15){let base=slawsCandidateLine(p,m),step=CFG[m].step,offset=risk<25?-2:risk<50?-1:risk<75?0:risk<92?1:2,line=Math.max(m==="receptions"?.5:0,base.line+offset*step),probability=overProbability(base.projection,line,m);return{p,m,s:consistency(p,m),projection:base.projection,line,probability,score:probability+(consistency(p,m)??0)*.01}}
function dailyGameCandidates(key,risk=15){let floor=risk<25?.62:risk<50?.55:risk<75?.48:risk<92?.34:.18,out=[];for(let p of DATA){if(!dailyEligible(p)||slawsGame({date:p.upcoming.date,team:p.team,opponent:p.upcoming.opponent})!==key)continue;for(let m of p.markets){let x=dailyLine(p,m,risk);if(x.s>=5&&x.probability>=floor)out.push(x)}}return out.sort((a,b)=>b.score-a.score)}
function dailyChoose(candidates,count){let chosen=[];for(let x of candidates){if(chosen.filter(y=>y.p.id===x.p.id).length>=1)continue;chosen.push(x);if(chosen.length===count)return chosen}for(let x of candidates){if(!chosen.includes(x)&&chosen.filter(y=>y.p.id===x.p.id).length<2)chosen.push(x);if(chosen.length===count)break}return chosen}
function dailyProbability(legs){if(!legs.length)return null;let same=legs.every(x=>slawsGame({date:x.p.upcoming.date,team:x.p.team,opponent:x.p.upcoming.opponent})===slawsGame({date:legs[0].p.upcoming.date,team:legs[0].p.team,opponent:legs[0].p.upcoming.opponent})),joint=same&&legs.length>1?slawsJointProbability(legs):null;return{p:joint?.probability??legs.reduce((v,x)=>v*x.probability,1),joint:!!joint}}
function dailyVerdict(p){return p>=.35?["Higher-probability parlay","good"]:p>=.18?["Reasonable only as a paper test",""]:p>=.08?["Unlikely to hit","warn"]:p>=.03?["Very unlikely to hit","danger"]:["Next to impossible to hit","danger"]}
function dailyLegHtml(x){return`<li><b>${x.p.name} over ${x.line.toFixed(1)} ${CFG[x.m].label.toLowerCase()}</b><span>${Math.round(x.probability*100)}% • ${x.s}/10 consistency</span></li>`}
function dailyGameRows(){let all=slawsGameOptions().map(g=>{let c=dailyGameCandidates(g.key,15),top=c[0],strength=c.slice(0,4).reduce((v,x)=>v+x.probability,0)+Math.min(c.length,10)*.02;return{...g,c,top,strength}}).filter(g=>g.top),groups=new Map();for(let g of all){if(!groups.has(g.date))groups.set(g.date,[]);groups.get(g.date).push(g)}let today=new Date().toLocaleDateString("en-CA"),dates=[...groups.keys()].sort(),target=dates.find(d=>d>=today&&groups.get(d).length>=3)||dates.sort((a,b)=>groups.get(b).length-groups.get(a).length||a.localeCompare(b))[0],games=(groups.get(target)||[]).sort((a,b)=>b.strength-a.strength);return games.slice(0,3)}
function dailyBuildGame(index){let game=dailyGameRows()[index],root=document.getElementById(`dailyBuild${index}`),count=Math.max(2,Math.min(7,+document.getElementById(`dailyLegs${index}`).value||3)),risk=+document.getElementById(`dailyRisk${index}`).value,c=dailyGameCandidates(game.key,risk),legs=dailyChoose(c,count);if(legs.length<count){root.innerHTML=`<div class="daily-warning">Only ${legs.length} eligible props clear the current role, availability, consistency, and risk screens. The model will not fill the parlay with weaker legs.</div>`;return}let result=dailyProbability(legs),[label,tone]=dailyVerdict(result.p);root.innerHTML=`<div class="daily-prob ${tone}"><strong>${Math.round(result.p*100)}%</strong><span>estimated chance<br><b>${label}</b></span></div><ol class="daily-legs">${legs.map(dailyLegHtml).join("")}</ol><div class="fine">${result.joint?"Historical same-game correlation applied.":"Independent baseline estimate."} These are model reference lines; confirm every FanDuel line and price.</div><button class="action daily-add" type="button">Add all to Slip Builder</button>`;root.querySelector(".daily-add").onclick=()=>{for(let x of legs){let leg=slawsCatalogLeg(x);if(!slawsSlip.some(y=>y.playerId===leg.playerId&&y.market===leg.market&&y.line===leg.line))slawsSlip.push(leg)}slawsParlayOdds=NaN;slawsSave();root.querySelector(".daily-add").textContent="Added to Slip Builder";root.querySelector(".daily-add").disabled=true}}
function dailyRender(){let root=document.getElementById("dailyBoard");if(!root||!DATA.length)return;let games=dailyGameRows();if(!games.length){root.innerHTML='<div class="daily-empty">No games currently clear the verified data and player-role screens.</div>';return}let straight=games.map(g=>g.top),multi=dailyProbability(straight),[multiLabel,multiTone]=dailyVerdict(multi.p),cardDate=new Date(games[0].date+"T12:00:00").toLocaleDateString(undefined,{weekday:"long",month:"short",day:"numeric"});root.innerHTML=`<div class="daily-head"><div><span class="daily-kicker">DAILY MODEL CARD</span><h2>Top ${games.length} games — ${cardDate}</h2><p>${games[0].date===new Date().toLocaleDateString("en-CA")?"Today’s":"Next full day’s"} games ranked by the depth and quality of available player-prop candidates.</p></div><div class="daily-combo ${multiTone}"><small>${games.length}-game parlay</small><strong>${Math.round(multi.p*100)}%</strong><span>${multiLabel}</span></div></div><div class="daily-games">${games.map((g,i)=>`<article class="daily-game"><div class="daily-game-top"><span>GAME ${i+1}</span><b>${g.teams.join(" vs. ")}</b><small>${g.date}</small></div><div class="daily-straight"><small>Straight-bet candidate</small><b>${g.top.p.name} over ${g.top.line.toFixed(1)} ${CFG[g.top.m].label.toLowerCase()}</b><span>${Math.round(g.top.probability*100)}% model estimate</span></div><details><summary>Build a parlay for this game</summary><div class="daily-controls"><label>Legs<input id="dailyLegs${i}" type="number" min="2" max="7" value="3"></label><label class="daily-risk">Risk <span id="dailyRiskLabel${i}">Safer</span><input id="dailyRisk${i}" type="range" min="0" max="100" value="15"></label><button class="action" data-build="${i}" type="button">Generate</button></div><div id="dailyBuild${i}" class="daily-build"></div></details></article>`).join("")}</div><div class="daily-parlay"><div><small>ONE LEG FROM EACH FEATURED GAME</small><h3>Model’s ${games.length}-game parlay</h3></div><ol class="daily-legs">${straight.map(dailyLegHtml).join("")}</ol><div class="daily-prob ${multiTone}"><strong>${Math.round(multi.p*100)}%</strong><span>estimated chance<br><b>${multiLabel}</b></span></div></div><p class="daily-disclaimer">Research card only. Probabilities are model estimates, not guarantees. Verify exact FanDuel lines, odds, injuries, and active players before making any decision.</p>`;root.querySelectorAll("[data-build]").forEach(b=>b.onclick=()=>dailyBuildGame(+b.dataset.build));games.forEach((g,i)=>{let risk=document.getElementById(`dailyRisk${i}`),label=document.getElementById(`dailyRiskLabel${i}`);risk.oninput=()=>{label.textContent=risk.value<25?"Safer":risk.value<50?"Conservative":risk.value<75?"Balanced":risk.value<92?"Aggressive":"Extreme"}})}
function dailySetup(){let timer=setInterval(()=>{if(DATA.length&&slawsActiveWeek!=null){clearInterval(timer);dailyRender();document.getElementById("activeWeek")?.addEventListener("change",()=>setTimeout(dailyRender,0))}},100)}
dailySetup();
function slawsRefreshGames(){let games=slawsGameOptions(),game=document.getElementById("sgpGame");game.innerHTML='<option value="">Choose a game</option>'+games.map(x=>`<option value="${x.key}">Week ${x.week} • ${x.teams.join(" vs. ")} • ${x.date}</option>`).join("")}
let slawsBannerTimer=setInterval(()=>{if(DATA.length){clearInterval(slawsBannerTimer);let teams=[...new Set(DATA.map(x=>x.team))].sort(),team=document.getElementById("catalogTeam"),week=document.getElementById("activeWeek");team.innerHTML='<option value="">All teams</option>'+teams.map(x=>`<option value="${x}">${x}</option>`).join("");let weeks=[...new Set(DATA.map(x=>x.upcoming.week))].sort((a,b)=>a-b);week.innerHTML=weeks.map(x=>`<option value="${x}" ${x===slawsActiveWeek?"selected":""}>Week ${x}</option>`).join("");week.onchange=()=>{slawsActiveWeek=+week.value;active=null;UI.detail.classList.add("hidden");slawsRefreshGames();UI.status.textContent=UI.status.textContent.replace(/^Week \d+/,`Week ${slawsActiveWeek}`);renderBrowse();renderConsistent();renderBears();slawsRenderBanner();slawsRenderCatalog()};slawsRefreshGames();slawsRenderBanner();slawsRenderCatalog()}},100);
